() => {
  const [count, setCount] = useState(0)
  const onClick = () => {
    setCount(count + 1)
    announce(`Watch ${count + 1}`)
  }
  return (
    <>
      <Button onClick={onClick} count={count}>
        Watch
      </Button>
      <AccessibilityNote />
      <p>
        In this example, a live region has been implemented to communicate the
        change.
      </p>
    </>
  )
}

() => {
  const [isLoading, setIsLoading] = useState(false)
  const handleClick = () => {
    setIsLoading(true)
  }
  return (
    <Button
      loading={isLoading}
      onClick={handleClick}
      leadingVisual={DownloadIcon}
    >
      Export
    </Button>
  )
}

